const fs=require('fs'),p=process.platform,e=process.env;
const has=l=>l.some(x=>x&&fs.existsSync(x));
const W=[e.PROGRAMFILES,e['PROGRAMFILES(X86)'],e.LOCALAPPDATA];
const chrome=p==='win32'?has(W.map(b=>b&&b+'\Google\Chrome\Application\chrome.exe')):p==='darwin'?has(['/Applications/Google Chrome.app']):has(['/usr/bin/google-chrome','/usr/bin/google-chrome-stable','/opt/google/chrome/chrome']);
const edge=p==='win32'?has(W.map(b=>b&&b+'\Microsoft\Edge\Application\msedge.exe')):p==='darwin'?has(['/Applications/Microsoft Edge.app']):has(['/usr/bin/microsoft-edge','/opt/microsoft/msedge/msedge']);
let c=(e.INFANTRY_BROWSER||'auto').toLowerCase();
if(c==='chrome'&&!chrome||c==='msedge'&&!edge)c='auto';
if(c==='auto')c=chrome?'chrome':edge?'msedge':'chromium';
const r=require('child_process').spawn(p==='win32'?'npx.cmd':'npx',['-y','@playwright/mcp@0.0.85','--isolated','--browser',c],{stdio:'inherit',shell:p==='win32'});
r.on('exit',x=>process.exit(x||0));
